# id suffix, name, domain, regime, g, maturity, summary, {space: {dimension: (min, max, status) or None}}
# dimension order: o2, pressure kPa, airflow m/s, temperature C, relative humidity %, co2, n2
_D = ("o2_fraction", "pressure_kpa", "airflow_ms", "temperature_c", "relative_humidity_pct", "co2_fraction", "n2_fraction")


def _spaces(**spaces):
    return {name: dict(zip(_D, vals)) for name, vals in spaces.items()}


